<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Event\LoginFailedEvent;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Event\LoginSucceededEvent;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Event\UserLockedEvent;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Event\UserUnlockedEvent;

final class OAuthDomainEventsUnitTest extends TestCase
{
    public function test_login_failed_event_stores_properties(): void
    {
        $at = new DateTimeImmutable('2026-01-01 10:00:00');
        $event = new LoginFailedEvent('tenant-1', 'user@x.com', 'bad-credentials', $at);

        $this->assertSame('tenant-1', $event->tenant);
        $this->assertSame('user@x.com', $event->username);
        $this->assertSame('bad-credentials', $event->reason);
        $this->assertSame($at, $event->occurredAt);
    }

    public function test_login_failed_event_default_occurred_at(): void
    {
        $before = new DateTimeImmutable();
        $event = new LoginFailedEvent('t', 'u', 'r');
        $after = new DateTimeImmutable();

        $this->assertGreaterThanOrEqual($before->getTimestamp(), $event->occurredAt->getTimestamp());
        $this->assertLessThanOrEqual($after->getTimestamp(), $event->occurredAt->getTimestamp());
    }

    public function test_login_succeeded_event_stores_properties(): void
    {
        $at = new DateTimeImmutable('2026-06-01');
        $event = new LoginSucceededEvent('tenant-2', 'user-1', 'client-a', 'sess-x', 'authorization_code', $at);

        $this->assertSame('tenant-2', $event->tenant);
        $this->assertSame('user-1', $event->userId);
        $this->assertSame('client-a', $event->clientId);
        $this->assertSame('sess-x', $event->sessionId);
        $this->assertSame('authorization_code', $event->grantType);
        $this->assertSame($at, $event->occurredAt);
    }

    public function test_user_locked_event_stores_properties(): void
    {
        $lockedUntil = new DateTimeImmutable('+30 minutes');
        $event = new UserLockedEvent('t', 'user-99', $lockedUntil);

        $this->assertSame('t', $event->tenant);
        $this->assertSame('user-99', $event->userId);
        $this->assertSame($lockedUntil, $event->lockedUntil);
    }

    public function test_user_unlocked_event_stores_properties(): void
    {
        $at = new DateTimeImmutable('2026-03-15');
        $event = new UserUnlockedEvent('tenant-3', 'user-7', $at);

        $this->assertSame('tenant-3', $event->tenant);
        $this->assertSame('user-7', $event->userId);
        $this->assertSame($at, $event->occurredAt);
    }
}
